// An AI assistant's comment: "Each worker owns slot id, so there is no sharing."
func count(workers, n int) int64 {
	counts := make([]atomic.Int64, workers)
	var wg sync.WaitGroup
	for id := range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range n {
				counts[id].Add(1)
			}
		}()
	}
	wg.Wait()
	var total int64
	for i := range counts {
		total += counts[i].Load()
	}
	return total
}
